sp_widget.client_script:
api.controller = function () {
    /* widget controller */
    var c = this;
};

sp_widget.css:
.sp-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-large;
  box-shadow: 0 1px 4px rgba($text-color, 0.07);
  background: $background-primary;
  overflow: hidden;
  margin-bottom: 0;
}
.sp-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  background: $background-primary;
  border-bottom: 1px solid $border-tertiary;
  min-height: 52px;
  flex-shrink: 0;
}
.sp-card-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin: 0;
}
.sp-card-icon {
  margin-right: 8px;
  color: $brand-primary;
  font-size: 16px;
}
.sp-card-body {
  padding: 24px;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
}
.sp-announcement-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.sp-announcement-item {
  padding-bottom: 16px;
  border-bottom: 1px solid $border-tertiary;
  &:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }
}
.sp-announcement-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}
.sp-announcement-date {
  font-size: 12px;
}
.sp-announcement-title {
  font-size: $font-size-base;
  font-weight: 600;
  color: $text-color;
  margin: 4px 0;
}
.sp-announcement-desc {
  font-size: $font-size-small;
  margin: 0;
  line-height: 1.5;
}

sp_widget.script:
(function() {
  data.announcements = [];

  data.announcements.push({
    title: 'Flash v2.0 Released',
    date: 'Dec 15, 2024',
    type: 'info',
    description: 'New features including group notifications and improved delivery tracking.'
  });
  data.announcements.push({
    title: 'Scheduled Maintenance',
    date: 'Dec 20, 2024',
    type: 'warning',
    description: 'Flash services will be briefly unavailable from 2:00 AM - 4:00 AM EST.'
  });
  data.announcements.push({
    title: 'New Feature: Group Notifications',
    date: 'Dec 10, 2024',
    type: 'success',
    description: 'You can now send flash notifications to entire user groups at once.'
  });
})();
